  IF v_after IS DISTINCT FROM v_before THEN
    SELECT string_agg(k || ' ' || coalesce(v_before->>k, '?') || '->' || coalesce(v_after->>k, '?'), '; ') INTO v_t
      FROM (SELECT k FROM jsonb_object_keys(v_before || v_after) k WHERE (v_before->>k) IS DISTINCT FROM (v_after->>k) LIMIT 5) z;
