  IF (SELECT md5(string_agg(md5(pg_get_functiondef(p.oid)), ',' ORDER BY p.oid::regprocedure::text)) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prokind = 'f' AND p.proname NOT IN ('is_leadership', 'is_department_admin', 'is_announcer')) IS DISTINCT FROM v_others THEN RAISE EXCEPTION 'Post-condition failed: a public function other than the three changed. Rolling back.'; END IF;
