  'is_announcer', jsonb_build_object('md5', (SELECT md5(pg_get_functiondef(p.oid)) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'is_announcer' AND p.prokind = 'f'), 'row', (SELECT p.prosecdef::text || '|' || p.provolatile::text || '|' || coalesce(p.proconfig::text, '') || '|' || coalesce(p.proacl::text, '') FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'is_announcer' AND p.prokind = 'f')),
